export interface ComplianceItem {
  product_id: string;
  product_name: string;
  risk_level: 'high' | 'medium' | 'low';
  violation_type: string;
  violation_detail: string;
  detected_at: string;
  status: 'pending' | 'ignored' | 'resolved';
  [key: string]: unknown;
}

export interface MediaItem {
  media_id: string;
  type: 'video' | 'image';
  title: string;
  status: string;
  source_url: string;
  output_url: string;
  create_time: string;
  [key: string]: unknown;
}

