  inventory_low_threshold?: number;
  notification_email?: string;
  enabled?: boolean;
  video_view_drop_threshold?: number;
  video_like_drop_threshold?: number;
  creator_follower_drop_threshold?: number;
  product_sales_drop_threshold?: number;
