  getList: (params?: Record<string, unknown>) => api.get<PaginatedResponse<Creator>>('/creators', { params }) as unknown as Promise<PaginatedResponse<Creator>>,
  getDetail: (id: string) => api.get<Creator>(`/creators/${id}`) as unknown as Promise<Creator>,
};

