  getStats: (params?: Record<string, unknown>) => api.get<DashboardStatsResponse>('/dashboard/stats', { params }) as unknown as Promise<DashboardStatsResponse>,
  getMockStatus: () => api.get<MockStatusResponse>('/mock/status') as unknown as Promise<MockStatusResponse>,
