export const alertApi = {
  getConfig: () => api.get<AlertConfig>('/alerts/config') as unknown as Promise<AlertConfig>,
  updateConfig: (config: AlertConfig) => api.post<AlertConfig>('/alerts/config', config) as unknown as Promise<AlertConfig>,
};

export const syncApi = {
  manualSync: () => api.post<{ last_update: string }>('/sync') as unknown as Promise<{ last_update: string }>,
};

export const healthApi = {
  check: () => api.get<HealthResponse>('/health') as unknown as Promise<HealthResponse>,
  getHealth: () => api.get<HealthResponse>('/health') as unknown as Promise<HealthResponse>,
};

export const videoApi = {
  getList: (params?: Record<string, unknown>) => api.get<PaginatedResponse<Video>>('/videos', { params }) as unknown as Promise<PaginatedResponse<Video>>,
  getDetail: (id: string) => api.get<Video>(`/videos/${id}`) as unknown as Promise<Video>,
  create: (data: Partial<Video>) => api.post<Video>('/videos', data) as unknown as Promise<Video>,
  update: (id: string, data: Partial<Video>) => api.put<Video>(`/videos/${id}`, data) as unknown as Promise<Video>,
  delete: (id: string) => api.delete<unknown>(`/videos/${id}`) as unknown as Promise<unknown>,
