export const authApi = {
  getStatus: () => api.get<AuthStatus>('/auth/status') as unknown as Promise<AuthStatus>,
  login: () => api.get<{ auth_url: string }>('/auth/login') as unknown as Promise<{ auth_url: string }>,
  logout: () => api.post<unknown>('/auth/logout') as unknown as Promise<unknown>,
  getQrCode: () => api.get<{ qr_code: string }>('/auth/qr-code') as unknown as Promise<{ qr_code: string }>,
};

export const accountApi = {
  getList: (params?: Record<string, unknown>) => api.get<PaginatedResponse<Account>>('/accounts', { params }) as unknown as Promise<PaginatedResponse<Account>>,
  getDetail: (id: string) => api.get<Account>(`/accounts/${id}`) as unknown as Promise<Account>,
  create: (data: Partial<Account>) => api.post<Account>('/accounts', data) as unknown as Promise<Account>,
  update: (id: string, data: Partial<Account>) => api.put<Account>(`/accounts/${id}`, data) as unknown as Promise<Account>,
  delete: (id: string) => api.delete<unknown>(`/accounts/${id}`) as unknown as Promise<unknown>,
};

export const complianceApi = {
  getList: (params?: Record<string, unknown>) => api.get<PaginatedResponse<ComplianceItem>>('/compliance', { params }) as unknown as Promise<PaginatedResponse<ComplianceItem>>,
  ignore: (id: string) => api.post<ComplianceItem>(`/compliance/${id}/ignore`) as unknown as Promise<ComplianceItem>,
  takeDown: (id: string) => api.post<ComplianceItem>(`/compliance/${id}/take-down`) as unknown as Promise<ComplianceItem>,
  restore: (id: string) => api.post<ComplianceItem>(`/compliance/${id}/restore`) as unknown as Promise<ComplianceItem>,
};

export const mediaApi = {
  getVideoEditList: (params?: Record<string, unknown>) => api.get<PaginatedResponse<MediaItem>>('/media/video-edit', { params }) as unknown as Promise<PaginatedResponse<MediaItem>>,
  getImageEditList: (params?: Record<string, unknown>) => api.get<PaginatedResponse<MediaItem>>('/media/image-edit', { params }) as unknown as Promise<PaginatedResponse<MediaItem>>,
  create: (data: Partial<MediaItem>) => api.post<MediaItem>('/media', data) as unknown as Promise<MediaItem>,
  update: (id: string, data: Partial<MediaItem>) => api.put<MediaItem>(`/media/${id}`, data) as unknown as Promise<MediaItem>,
};

export const alertDouyinApi = {
  getConfig: () => api.get<AlertConfig>('/alerts/douyin/config') as unknown as Promise<AlertConfig>,
  updateConfig: (config: AlertConfig) => api.post<AlertConfig>('/alerts/douyin/config', config) as unknown as Promise<AlertConfig>,
};

export const alertDianApi = {
  getConfig: () => api.get<AlertConfig>('/alerts/dian/config') as unknown as Promise<AlertConfig>,
  updateConfig: (config: AlertConfig) => api.post<AlertConfig>('/alerts/dian/config', config) as unknown as Promise<AlertConfig>,
};

export default api;

