import { useState, useEffect, useCallback } from 'react';

export interface UseApiState<T> {
  data: T | null;
  loading: boolean;
  error: Error | null;
}

export interface UseApiReturn<T> extends UseApiState<T> {
  refetch: () => Promise<T>;
}

type Thenable<T> = PromiseLike<T> | T;

// eslint-disable-next-line react-hooks/set-state-in-effect
export function useApi<T>(apiCall: () => Thenable<T>, dependencies: unknown[] = []): UseApiReturn<T> {
  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  const fetchData = useCallback(async (): Promise<T> => {
    try {
      setLoading(true);
      setError(null);
      const result = await apiCall();
      setData(result);
      return result;
    } catch (err) {
      const error = err instanceof Error ? err : new Error(String(err));
      setError(error);
      throw error;
    } finally {
      setLoading(false);
    }
  }, [apiCall]);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchData();
  }, dependencies);

  return { data, loading, error, refetch: fetchData };
}

// eslint-disable-next-line react-hooks/set-state-in-effect
export function usePolling<T>(apiCall: () => Thenable<T>, interval = 30000): UseApiReturn<T> {
  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  const fetchData = useCallback(async (): Promise<T> => {
    try {
      setLoading(true);
      setError(null);
      const result = await apiCall();
      setData(result);
      return result;
    } catch (err) {
      const error = err instanceof Error ? err : new Error(String(err));
      setError(error);
      throw error;
    } finally {
      setLoading(false);
    }
  }, [apiCall]);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchData();
    const timer = setInterval(fetchData, interval);
    return () => clearInterval(timer);
  }, [fetchData, interval]);

  return { data, loading, error, refetch: fetchData };
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom';
import { ConfigProvider } from 'antd';
import zhCN from 'antd/locale/zh_CN';
import App from './App';
import './index.css';

export function mount() {
  const root = ReactDOM.createRoot(document.getElementById('root'));
  root.render(
    <React.StrictMode>
      <ConfigProvider locale={zhCN}>
        <BrowserRouter>
          <App />
        </BrowserRouter>
      </ConfigProvider>
    </React.StrictMode>
  );
}

// 立即执行并挂载到 window，防止被 tree-shaking 移除
if (typeof window !== 'undefined') {
  (window as any).__APP_MOUNT__ = mount;
  mount();
}

import React, { useState, useMemo, useCallback } from 'react';
import type { FormInstance } from 'antd';
import { Card, Table, Input, Button, Select, Space, Spin, Form, message, Tag, Avatar, Modal, Descriptions, Switch } from 'antd';
import { SearchOutlined, ReloadOutlined, DownloadOutlined, UserOutlined, SettingOutlined } from '@ant-design/icons';
import { accountApi, type Account, type PaginatedResponse } from '@/api/index';
import { useApi } from '@/hooks/useApi';
import { formatDateTime } from '@/utils/formatters';

type AccountRecord = Account;

interface ColumnItem {
  title: string;
  dataIndex: string;
  key: string;
  width?: number;
  align?: 'left' | 'right' | 'center';
  render?: (value: any, record: AccountRecord) => React.ReactNode;
  onCell?: (record: AccountRecord) => { onClick: () => void; style: { cursor: string } };
}

const Account = () => {
  const [searchText, setSearchText] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);
  const [detailModal, setDetailModal] = useState({ visible: false, account: null as AccountRecord | null });
  const [formModal, setFormModal] = useState({ visible: false, editing: null as AccountRecord | null });
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  const formRef = React.useRef<FormInstance<any> | null>(null);

  const { data, loading, error, refetch } = useApi<PaginatedResponse<AccountRecord>>(
    () => accountApi.getList({ 
      page, 
      size: pageSize, 
      keyword: searchText,
      status: statusFilter,
    }),
    [page, pageSize, searchText, statusFilter]
  );

  const handleSearch = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchText(e.target.value);
    setPage(1);
  };

  const handleStatusChange = (value: string) => {
    setStatusFilter(value);
    setPage(1);
  };

  const handleTableChange = (pagination: { current: number; pageSize: number }) => {
    if (pagination) {
      setPage(pagination.current);
      setPageSize(pagination.pageSize);
    }
  };

  const handleViewDetail = useCallback((account: AccountRecord) => {
    setDetailModal({ visible: true, account });
  }, []);

  const handleEdit = useCallback((account: AccountRecord) => {
    setFormModal({ visible: true, editing: account });
  }, []);

  const handleCreate = useCallback(() => {
    setFormModal({ visible: true, editing: null });
  }, []);

  const handleDelete = useCallback(async (account: AccountRecord) => {
    try {
      if (window.confirm(`确定要删除账号 ${account.account_name} 吗？`)) {
        message.loading('删除中...', 0);
        await accountApi.delete(account.account_id);
        message.destroy();
        message.success('删除成功');
        refetch();
      }
    } catch (err) {
      message.destroy();
      message.error('删除失败');
    }
  }, [refetch]);

  const handleFormSubmit = async (values: Partial<AccountRecord>) => {
    try {
      if (formModal.editing) {
        await accountApi.update(formModal.editing.account_id, values);
      } else {
        await accountApi.create(values);
      }
      message.success('账号保存成功');
      setFormModal({ visible: false, editing: null });
      refetch();
    } catch (err) {
      message.error('保存失败: ' + (err instanceof Error ? err.message : String(err)));
    }
  };

  const tableColumns = useMemo<ColumnItem[]>(() => [
    {
      title: '账号ID',
      dataIndex: 'account_id',
      key: 'account_id',
      width: 120,
    },
    {
      title: '账号名称',
      dataIndex: 'account_name',
      key: 'account_name',
      width: 150,
      onCell: (record) => ({
        onClick: () => handleViewDetail(record),
        style: { cursor: 'pointer' },
      }),
    },
    {
      title: '账号类型',
      dataIndex: 'account_type',
      key: 'account_type',
      width: 100,
      align: 'center',
      render: (type) => (
        <Tag color={type === 'official' ? 'blue' : type === 'personal' ? 'green' : 'orange'}>
          {type === 'official' ? '官方号' : type === 'personal' ? '个人号' : type}
        </Tag>
      ),
    },
    {
      title: '绑定手机',
      dataIndex: 'phone',
      key: 'phone',
      width: 150,
    },
    {
      title: '绑定邮箱',
      dataIndex: 'email',
      key: 'email',
      width: 200,
    },
    {
      title: '状态',
      dataIndex: 'status',
      key: 'status',
      width: 100,
      align: 'center',
      render: (status) => (
        <Tag color={status === 'active' ? 'green' : status === 'inactive' ? 'orange' : 'red'}>
          {status === 'active' ? '正常' : status === 'inactive' ? '停用' : '异常'}
        </Tag>
      ),
    },
    {
      title: '最后登录',
      dataIndex: 'last_login',
      key: 'last_login',
      width: 180,
      render: formatDateTime,
    },
    {
      title: '操作',
      dataIndex: 'action',
      key: 'action',
      width: 180,
      render: (_, record: AccountRecord) => (
        <Space>
          <Button type="link" icon={<SettingOutlined />} size="small">设置</Button>
          <Button type="link" danger size="small" onClick={() => handleDelete(record)}>删除</Button>
        </Space>
      ),
    },
  ], [handleViewDetail, handleDelete, formatDateTime]);

  if (loading && !data) {
    return <Spin size="large" tip="加载账号数据..." />;
  }

  if (error) {
    return (
      <Card>
        <div style={{ textAlign: 'center', padding: 40 }}>
          <p style={{ color: '#ff4d4f' }}>加载失败: {error instanceof Error ? error.message : String(error)}</p>
          <Button type="primary" onClick={refetch} icon={<ReloadOutlined />}>
            重试
          </Button>
        </div>
      </Card>
    );
  }

  const accounts: AccountRecord[] = data?.data || [];
  const total = data?.total || 0;

  return (
    <div className="page-container">
      <div className="page-header">
        <h1 className="page-title">账号管理</h1>
        <Space wrap>
          <Input
            placeholder="搜索账号名称/ID..."
            value={searchText}
            onChange={(e) => { setSearchText(e.target.value); setPage(1); }}
            prefix={<SearchOutlined />}
            style={{ width: 250 }}
            allowClear
          />
          <Select
            placeholder="账号状态"
            value={statusFilter}
            onChange={(value) => { setStatusFilter(value); setPage(1); }}
            allowClear
            style={{ width: 140 }}
            options={[
              { value: 'active', label: '正常' },
              { value: 'inactive', label: '停用' },
              { value: 'error', label: '异常' },
            ]}
          />
          <Button type="primary" icon={<UserOutlined />} onClick={handleCreate}>新增账号</Button>
          <Button icon={<DownloadOutlined />} onClick={handleExport}>导出 CSV</Button>
          <Button icon={<ReloadOutlined />} onClick={refetch} loading={loading}>刷新</Button>
        </Space>
      </div>

      <Card className="table-container">
        <Table
          columns={tableColumns.map(col => ({
            ...col,
            onCell: col.dataIndex === 'account_name' ? (record: AccountRecord) => ({
              onClick: () => handleViewDetail(record),
              style: { cursor: 'pointer' },
            }) : undefined,
          }))}
          dataSource={accounts}
          pagination={{
            current: page,
            pageSize,
            total,
            showSizeChanger: true,
            showQuickJumper: true,
            showTotal: (total) => `共 ${total} 条`,
          }}
          onChange={handleTableChange}
          rowKey="account_id"
          loading={loading}
        />
      </Card>

      <Modal
        title="账号详情"
        visible={detailModal.visible}
        onOk={() => setDetailModal({ ...detailModal, visible: false })}
        onCancel={() => setDetailModal({ ...detailModal, visible: false })}
        width={600}
      >
        {detailModal.account && (
          <Descriptions column={2} title="基本信息">
            <Descriptions.Item label="账号ID">{detailModal.account.account_id}</Descriptions.Item>
            <Descriptions.Item label="账号名称">{detailModal.account.account_name}</Descriptions.Item>
            <Descriptions.Item label="账号类型">{detailModal.account.account_type === 'official' ? '官方号' : detailModal.account.account_type === 'personal' ? '个人号' : detailModal.account.account_type}</Descriptions.Item>
            <Descriptions.Item label="绑定手机">{detailModal.account.phone}</Descriptions.Item>
            <Descriptions.Item label="绑定邮箱">{detailModal.account.email}</Descriptions.Item>
            <Descriptions.Item label="状态">{detailModal.account.status === 'active' ? '正常' : detailModal.account.status === 'inactive' ? '停用' : '异常'}</Descriptions.Item>
            <Descriptions.Item label="最后登录">{formatDateTime(detailModal.account.last_login)}</Descriptions.Item>
          </Descriptions>
        )}
      </Modal>

      <Modal
        title={formModal.editing ? '编辑账号' : '新增账号'}
        visible={formModal.visible}
        onOk={() => formRef.current?.validateFields().then(handleFormSubmit).catch(() => {})}
        onCancel={() => setFormModal({ visible: false, editing: null })}
        width={500}
      >
        <Form
          ref={formRef}
          layout="vertical"
          initialValues={formModal.editing || {}}
        >
          <Form.Item name="account_name" label="账号名称" rules={[{ required: true, message: '请输入账号名称' }]}>
            <Input placeholder="请输入账号名称" />
          </Form.Item>
          <Form.Item name="account_type" label="账号类型" rules={[{ required: true, message: '请选择账号类型' }]}>
            <Select placeholder="请选择账号类型">
              <Select.Option value="official">官方号</Select.Option>
              <Select.Option value="personal">个人号</Select.Option>
            </Select>
          </Form.Item>
          <Form.Item name="phone" label="绑定手机">
            <Input placeholder="请输入手机号" />
          </Form.Item>
          <Form.Item name="email" label="绑定邮箱">
            <Input placeholder="请输入邮箱" />
          </Form.Item>
          <Form.Item name="status" label="状态" valuePropName="checked">
            <Switch checkedChildren="正常" unCheckedChildren="停用" />
          </Form.Item>
        </Form>
      </Modal>
    </div>
  );
};

const handleExport = async () => {
  try {
    message.loading('导出中...', 0);
    const result = await accountApi.getList({ page: 1, size: 10000 });
    message.destroy();

    const csvContent = [
      ['账号ID', '账号名称', '账号类型', '绑定手机', '绑定邮箱', '状态', '最后登录'],
      ...(result?.data || []).map((a: AccountRecord) => [
        a.account_id,
        a.account_name,
        a.account_type,
        a.phone,
        a.email,
        a.status,
        a.last_login,
      ]),
    ].map(row => row.map(cell => `"${cell}"`).join(',')).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `accounts_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
    message.success('导出成功');
  } catch (err) {
    message.destroy();
    message.error('导出失败');
  }
};

export default Account;

import React, { useState } from 'react';
import { Card, Form, Input, InputNumber, Switch, Button, Space, message, Alert, Divider, Tabs, Select } from 'antd';
import { ReloadOutlined, CheckOutlined, ShopOutlined, BellOutlined } from '@ant-design/icons';
import { alertDianApi, type AlertConfig } from '@/api/index';
import { useApi } from '@/hooks/useApi';

const AlertsDian = () => {
  const [form] = Form.useForm();
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  const [activeTab, setActiveTab] = useState('sales');

  const { data, loading, error, refetch } = useApi<AlertConfig>(alertDianApi.getConfig);

  const defaultValues: AlertConfig = {
    product_sales_drop_threshold: 0.3,
    order_refund_rate_threshold: 0.15,
    compliance_risk_threshold: 'medium',
    notification_email: '',
    enabled: true,
  };

  const initialValues = data || defaultValues;

  const MIN_THRESHOLD = 0.01 satisfies 0.01 | 1;



  const onFinish = async (values) => {
    setSaving(true);
    setSaved(false);
    try {
      await alertDianApi.updateConfig(values);
      message.success('抖店告警配置保存成功');
      setSaved(true);
      refetch();
    } catch (err) {
      message.error('保存失败: ' + err.message);
    } finally {
      setSaving(false);
    }
  };

  const handleEnabledChange = (enabled) => {
    form.setFieldValue('enabled', enabled);
  };

  if (loading && !data) {
    return (
      <Card style={{ padding: 40, textAlign: 'center' }}>
        <div className="ant-spin-dot">
          <span></span><span></span><span></span><span></span>
        </div>
        <p style={{ marginTop: 16, color: '#8c8c8c' }}>加载配置中...</p>
      </Card>
    );
  }

  if (error) {
    return (
      <Alert message="加载配置失败" description={error.message} type="error" onClick={refetch} action="重试" closable showIcon />
    );
  }

  return (
    <div className="page-container">
      <div className="page-header">
        <h1 className="page-title">
          <ShopOutlined style={{ marginRight: 8 }} />
          <BellOutlined style={{ marginLeft: 8, marginRight: 8 }} />
          抖店告警配置
        </h1>
        <Button icon={<ReloadOutlined />} onClick={refetch} loading={loading}>刷新</Button>
      </div>

      <Tabs defaultActiveKey="sales" onChange={setActiveTab}>
        <Tabs.TabPane tab="销量告警" key="sales">
          <Card className="alert-config-form">
            <Form
              form={form}
              layout="vertical"
              initialValues={initialValues}
              onFinish={onFinish}
              colon={false}
            >
              <Form.Item
                name="enabled"
                label="启用抖店告警"
                valuePropName="checked"
              >
                <Switch onChange={handleEnabledChange} />
              </Form.Item>

              <Divider>商品销量告警</Divider>

              <Form.Item
                name="product_sales_drop_threshold"
                label="销量下跌阈值"
                help="当商品销量较前一日下跌超过此比例时触发告警"
                rules={[{ required: true, message: '请输入销量下跌阈值' }]}
              >
                {/* @ts-expect-error InputNumber props type mismatch */}
                <InputNumber
                  min={MIN_THRESHOLD}
                  max={1}
                  step={0.01}
                  precision={2}
                  style={{ width: 150 }}
                  formatter={v => v ? `${(v * 100).toFixed(0)}%` : ''}
                  // @ts-expect-error InputNumber props type mismatch
                  parser={v => v ? parseFloat(v.replace('%', '')) / 100 : undefined}
                  addonAfter="%"
                />
              </Form.Item>

              <Divider>订单退款率告警</Divider>

              <Form.Item
                name="order_refund_rate_threshold"
                label="退款率上升阈值"
                help="当订单退款率较前一日上升超过此比例时触发告警"
                rules={[{ required: true, message: '请输入退款率上升阈值' }]}
              >
                {/* @ts-expect-error InputNumber props type mismatch */}
                <InputNumber
                  min={MIN_THRESHOLD}
                  max={1}
                  step={0.01}
                  precision={2}
                  style={{ width: 150 }}
                  formatter={v => v ? `${(v * 100).toFixed(0)}%` : ''}
                  // @ts-expect-error InputNumber props type mismatch
                  parser={v => v ? parseFloat(v.replace('%', '')) / 100 : undefined}
                  addonAfter="%"
                />
              </Form.Item>

              <Divider>合规风险告警</Divider>

              <Form.Item
                name="compliance_risk_threshold"
                label="合规风险等级阈值"
                help="当商品合规风险等级达到或超过此级别时触发告警"
                rules={[{ required: true, message: '请选择合规风险等级' }]}
              >
                <Select style={{ width: 150 }}>
                  <Select.Option value="low">低风险</Select.Option>
                  <Select.Option value="medium">中风险</Select.Option>
                  <Select.Option value="high">高风险</Select.Option>
                </Select>
              </Form.Item>

              <Divider>通知设置</Divider>

              <Form.Item
                name="notification_email"
                label="告警通知邮箱"
                help="告警触发时将发送邮件通知到此邮箱（留空则不发送邮件）"
                rules={[{ type: 'email', message: '请输入有效的邮箱地址' }]}
              >
                <Input placeholder="admin@example.com" style={{ width: 300 }} />
              </Form.Item>

              <Divider />

              <Form.Item>
                <Space>
                  <Button
                    type="primary"
                    htmlType="submit"
                    loading={saving}
                    icon={saved ? <CheckOutlined /> : null}
                  >
                    {saved ? '已保存' : '保存配置'}
                  </Button>
                  <Button
                    onClick={() => {
                      form.setFieldsValue(initialValues);
                      setSaved(false);
                    }}
                  >
                    重置
                  </Button>
                </Space>
              </Form.Item>
            </Form>

            {saved && (
              <Alert
                message="配置已保存"
                description="抖店告警配置已更新，新的阈值将在下次检查时生效"
                type="success"
                showIcon
                closable
                onClose={() => setSaved(false)}
                style={{ marginTop: 16 }}
              />
            )}
          </Card>
        </Tabs.TabPane>

        <Tabs.TabPane tab="告警规则" key="rules">
          <Card style={{ marginTop: 24 }}>
            <h3 style={{ marginBottom: 16 }}>抖店告警规则说明</h3>
            <ul style={{ lineHeight: 2, color: '#595959' }}>
              <li><strong>商品销量下跌告警</strong>：监控每个商品的今日销量与昨日销量对比，当下跌幅度超过设定阈值时触发。</li>
              <li><strong>订单退款率上升告警</strong>：监控每日订单退款率，当退款率上升超过设定阈值时触发。</li>
              <li><strong>合规风险等级告警</strong>：监控商品合规风险等级，当风险等级达到或超过设定阈值时触发。</li>
              <li><strong>通知方式</strong>：目前支持邮件通知，配置邮箱后将在告警触发时发送邮件。后续可扩展钉钉、企业微信、飞书等通知渠道。</li>
              <li><strong>检查频率</strong>：系统每 5 分钟自动检查一次告警条件，也可在仪表盘点击&ldquo;立即同步&rdquo;手动触发检查。</li>
              <li><strong>平台范围</strong>：本配置仅针对抖店平台（商品、订单、店铺）的数据。</li>
            </ul>
          </Card>
        </Tabs.TabPane>
      </Tabs>
    </div>
  );
};

export default AlertsDian;

