import React, { useState } from 'react';
import { Card, Button, message, Divider, Space } from 'antd';
import { ReloadOutlined, QrcodeOutlined, LoginOutlined, LogoutOutlined } from '@ant-design/icons';
import { authApi, healthApi, type AuthStatus, type HealthResponse } from '@/api.index';
import { useApi } from '@/hooks/useApi';
import styles from './Auth.module.css';

const Auth = () => {
  const [qrCode, setQrCode] = useState(null);
  const [saving, setSaving] = useState(false);

  const { data: healthData, refetch: checkHealth } = useApi<HealthResponse>(healthApi.check, []);
  const { data: authData, loading: authLoading, refetch: refetchAuth } = useApi<AuthStatus>(authApi.getStatus, []);

  const authStatus = authData?.authorized ? 'authorized' : authLoading ? 'checking' : 'unauthorized';
  const authInfo = authData;

  const checkAuth = async () => {
    refetchAuth();
  };

  const handleLogin = async () => {
    try {
      const res = await authApi.login();
      if (res?.auth_url) {
        window.location.href = res.auth_url;
      }
    } catch (_err) {
      message.error('授权失败');
    }
  };

  const handleLogout = async () => {
    try {
      await authApi.logout();
      message.success('已撤销授权');
      checkAuth();
    } catch (err) {
      message.error('撤销授权失败');
    }
  };

  const handleRefreshQr = async () => {
    try {
      const res = await authApi.getQrCode();
      if (res?.qr_code) {
        setQrCode(res.qr_code);
      }
    } catch (_err) {
      message.error('获取二维码失败');
    }
  };

  return (
    <div className="page-container">
      <div className="page-header">
        <h1 className="page-title">授权管理</h1>
        <Space>
          <Button icon={<ReloadOutlined />} onClick={checkAuth} loading={authStatus === 'checking'}>刷新状态</Button>
          <Button icon={<QrcodeOutlined />} onClick={handleRefreshQr}>刷新二维码</Button>
        </Space>
      </div>

      <Card className="auth-card">
        <div className="auth-status">
          <div className={`status-indicator ${authStatus}`}>
            {authStatus === 'authorized' && '✅ 已授权'}
            {authStatus === 'unauthorized' && '❌ 未授权'}
            {authStatus === 'checking' && '⏳ 检查中...'}
            {authStatus === 'error' && '⚠️ 检查失败'}
          </div>
          <div className="status-actions">
            {authStatus === 'unauthorized' && (
              <Button type="primary" icon={<LoginOutlined />} onClick={handleLogin} size="large">
                授权登录
              </Button>
            )}
            {authStatus === 'authorized' && (
              <Button danger icon={<LogoutOutlined />} onClick={handleLogout} size="large">
                撤销授权
              </Button>
            )}
          </div>
        </div>

        <Divider>授权信息</Divider>
        <Card className="auth-info">
          {authInfo && (
            <>
              <p><strong>App ID:</strong> {authInfo.app_id || '-'}</p>
              <p><strong>Open ID:</strong> {authInfo.open_id || '-'}</p>
              <p><strong>Access Token:</strong> {authInfo.access_token ? authInfo.access_token.substring(0, 20) + '...' : '-'}</p>
              <p><strong>过期时间:</strong> {authInfo.expires_at ? new Date(authInfo.expires_at).toLocaleString() : '-'}</p>
              <p><strong>权限范围:</strong> {authInfo.scope?.join(', ') || '-'}</p>
            </>
          )}
          {!authInfo && <p className="no-info">暂无授权信息</p>}
        </Card>

        <Divider>扫码授权</Divider>
        <div className="qr-section">
          {qrCode ? (
            <img src={qrCode} alt="授权二维码" className="qr-code" />
          ) : (
            <div className="qr-placeholder">加载二维码中...</div>
          )}
          <p className="qr-tip">使用抖音APP扫码授权</p>
          <Button icon={<QrcodeOutlined />} onClick={handleRefreshQr}>刷新二维码</Button>
        </div>
      </Card>
    </div>
  );
};

export default Auth;

import React, { useState, useMemo, useCallback } from 'react';
import dayjs from 'dayjs';
import { Card, Table, Input, Button, Select, Space, Spin, DatePicker, message, Badge, Tag } from 'antd';
import { SearchOutlined, ReloadOutlined, DownloadOutlined } from '@ant-design/icons';
import { complianceApi, type ComplianceItem, type PaginatedResponse } from '@/api.index';
import { useApi } from '@/hooks/useApi';
import { formatNumber, formatStatus, formatDateTime } from '@/utils/formatters';

const { RangePicker } = DatePicker;
type DateRangeValue = [dayjs.Dayjs, dayjs.Dayjs] | [];

const Compliance = () => {
  const [searchText, setSearchText] = useState('');
  const [riskFilter, setRiskFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [dateRange, setDateRange] = useState<DateRangeValue>([]);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);

  const { data, loading, error, refetch } = useApi<PaginatedResponse<ComplianceItem>>(
    () => complianceApi.getList({ 
      page, 
      size: pageSize, 
      keyword: searchText,
      risk_level: riskFilter,
      status: statusFilter,
      start_date: dateRange[0]?.format('YYYY-MM-DD'),
      end_date: dateRange[1]?.format('YYYY-MM-DD'),
    }),
    [page, pageSize, searchText, riskFilter, statusFilter, dateRange]
  );

  const handleSearch = useCallback((e) => {
    setSearchText(e.target.value);
    setPage(1);
  }, []);

  const handleDateChange = useCallback((dates) => {
    setDateRange(dates);
    setPage(1);
  }, []);

  const handleRiskChange = useCallback((value) => {
    setRiskFilter(value);
    setPage(1);
  }, []);

  const handleStatusChange = useCallback((value) => {
    setStatusFilter(value);
    setPage(1);
  }, []);

  const handleTableChange = useCallback((pagination) => {
    if (pagination) {
      setPage(pagination.current);
      setPageSize(pagination.pageSize);
    }
  }, []);

  const handleIgnore = useCallback(async (record: ComplianceItem) => {
    try {
      message.loading('处理中...', 0);
      await complianceApi.ignore(record.product_id);
      message.destroy();
      message.success('已忽略');
      refetch();
    } catch (_err) {
      message.destroy();
      message.error('操作失败');
    }
  }, [refetch]);

  const handleTakeDown = useCallback(async (record: ComplianceItem) => {
    try {
      message.loading('下架中...', 0);
      await complianceApi.takeDown(record.product_id);
      message.destroy();
      message.success('已下架');
      refetch();
    } catch (_err) {
      message.destroy();
      message.error('下架失败');
    }
  }, [refetch]);

  const handleRestore = useCallback(async (record: ComplianceItem) => {
    try {
      message.loading('恢复中...', 0);
      await complianceApi.restore(record.product_id);
      message.destroy();
      message.success('已恢复');
      refetch();
    } catch (_err) {
      message.destroy();
      message.error('恢复失败');
    }
  }, [refetch]);

  const columns = useMemo(() => [
    {
      title: '商品ID',
      dataIndex: 'product_id',
      key: 'product_id',
      width: 120,
    },
    {
      title: '商品名称',
      dataIndex: 'product_name',
      key: 'product_name',
      width: 200,
      ellipsis: true,
    },
    {
      title: '风险等级',
      dataIndex: 'risk_level',
      key: 'risk_level',
      width: 100,
      align: 'center' as const,
      render: (level) => (
        <Badge status={level === 'high' ? 'error' : level === 'medium' ? 'warning' : 'success'} text={level === 'high' ? '高风险' : level === 'medium' ? '中风险' : '低风险'} />
      ),
    },
    {
      title: '违规类型',
      dataIndex: 'violation_type',
      key: 'violation_type',
      width: 150,
    },
    {
      title: '违规详情',
      dataIndex: 'violation_detail',
      key: 'violation_detail',
      width: 200,
      ellipsis: true,
    },
    {
      title: '检测时间',
      dataIndex: 'detected_at',
      key: 'detected_at',
      width: 180,
      render: formatDateTime,
    },
    {
      title: '状态',
      dataIndex: 'status',
      key: 'status',
      width: 100,
      align: 'center' as const,
      render: (status) => (
        <Tag color={status === 'pending' ? 'orange' : status === 'ignored' ? 'blue' : status === 'resolved' ? 'green' : 'default'}>
          {status === 'pending' ? '待处理' : status === 'ignored' ? '已忽略' : status === 'resolved' ? '已解决' : status}
        </Tag>
      ),
    },
    {
      title: '操作',
      key: 'action',
      width: 180,
      render: (_, record: ComplianceItem) => (
        <Space>
          {record.status === 'pending' && (
            <>
              <Button type="link" size="small" onClick={() => handleIgnore(record)}>忽略</Button>
              <Button type="link" size="small" danger onClick={() => handleTakeDown(record)}>下架</Button>
            </>
          )}
          {record.status === 'ignored' && (
            <Button type="link" size="small" onClick={() => handleRestore(record)}>恢复</Button>
          )}
        </Space>
      ),
    },
  ], [handleIgnore, handleTakeDown, handleRestore]);

  if (loading && !data) {
    return <Spin size="large" tip="加载合规数据..." />;
  }

  if (error) {
    return (
      <Card>
        <div style={{ textAlign: 'center', padding: 40 }}>
          <p style={{ color: '#ff4d4f' }}>加载失败: {error.message}</p>
          <Button type="primary" onClick={refetch} icon={<ReloadOutlined />}>
            重试
          </Button>
        </div>
      </Card>
    );
  }

  const compliance = data?.data || [];
  const total = data?.total || 0;

  return (
    <div className="page-container">
      <div className="page-header">
        <h1 className="page-title">合规管理</h1>
        <Space wrap>
          <Input
            placeholder="搜索商品名称/ID..."
            value={searchText}
            onChange={handleSearch}
            prefix={<SearchOutlined />}
            style={{ width: 250 }}
            allowClear
          />
          <RangePicker
            // @ts-expect-error RangePicker value type mismatch with moment/dayjs
            value={dateRange}
            onChange={handleDateChange}
            placeholder={['开始日期', '结束日期']}
            style={{ width: 300 }}
            allowClear
          />
          <Select
            placeholder="风险等级"
            value={riskFilter}
            onChange={handleRiskChange}
            allowClear
            style={{ width: 140 }}
            options={[
              { value: 'high', label: '高风险' },
              { value: 'medium', label: '中风险' },
              { value: 'low', label: '低风险' },
            ]}
          />
          <Select
            placeholder="处理状态"
            value={statusFilter}
            onChange={handleStatusChange}
            allowClear
            style={{ width: 140 }}
            options={[
              { value: 'pending', label: '待处理' },
              { value: 'ignored', label: '已忽略' },
              { value: 'resolved', label: '已解决' },
            ]}
          />
          <Button icon={<DownloadOutlined />} onClick={handleExport}>导出 CSV</Button>
          <Button icon={<ReloadOutlined />} onClick={refetch} loading={loading}>刷新</Button>
        </Space>
      </div>

      <Card className="table-container">
        <Table
          columns={columns}
          dataSource={compliance}
          pagination={{
            current: page,
            pageSize,
            total,
            showSizeChanger: true,
            showQuickJumper: true,
            showTotal: (total) => `共 ${total} 条`,
          }}
          onChange={handleTableChange}
          rowKey="product_id"
          loading={loading}
          scroll={{ x: 1300 }}
        />
      </Card>
    </div>
  );
};

const handleExport = async () => {
  try {
    message.loading('导出中...', 0);
    const result = await complianceApi.getList({ page: 1, size: 10000 });
    message.destroy();

    const csvContent = [
      ['商品ID', '商品名称', '风险等级', '违规类型', '违规详情', '检测时间', '状态'],
      ...(result?.data || []).map(c => [
        c.product_id,
        c.product_name,
        c.risk_level,
        c.violation_type,
        c.violation_detail,
        c.detected_at,
        c.status,
      ]),
    ].map(row => row.map(cell => `"${cell}"`).join(',')).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `compliance_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
    message.success('导出成功');
  } catch (err) {
    message.destroy();
    message.error('导出失败');
  }
};

export default Compliance;

import React, { useState, useMemo, useCallback } from 'react';
import { Card, Table, Input, Button, Space, Spin, message, Tag, Avatar, Modal, Descriptions } from 'antd';
import { SearchOutlined, ReloadOutlined, DownloadOutlined, UserOutlined } from '@ant-design/icons';
import { creatorApi, type Creator, type PaginatedResponse } from '@/api/index';
import { useApi } from '@/hooks/useApi';
import { formatNumber, formatDateTime } from '@/utils/formatters';

const Creator = () => {
  const [searchText, setSearchText] = useState('');
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);
