    () => creatorApi.getList({ page, size: pageSize, keyword: searchText }),
    [page, pageSize, searchText]
  );

  const handleSearch = (e) => {
    setSearchText(e.target.value);
    setPage(1);
  };

  const handleViewDetail = useCallback(async (creator: Creator) => {
