  const handleTableChange = (pagination) => {
    if (pagination) {
      setPage(pagination.current);
      setPageSize(pagination.pageSize);
    }
  };

  const handleExport = async () => {
    try {
      message.loading('导出中...', 0);
      const result = await creatorApi.getList({ page: 1, size: 10000 });
      message.destroy();

      const csvContent = [
        ['创作者ID', '昵称', '粉丝数', '总销量', '总收入', '带货商品数', '平均转化率', '更新时间'],
        ...(result?.data || []).map(c => [
          c.creator_id,
          c.nickname,
          c.followers,
          c.total_sales,
          c.total_revenue,
          c.product_count,
          c.avg_conversion_rate ? ((c.avg_conversion_rate as number) * 100).toFixed(2) + '%' : '-',
          c.fetched_at,
        ]),
      ].map(row => row.map(cell => `"${cell}"`).join(',')).join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `creators_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
      message.success('导出成功');
    } catch (err) {
      message.destroy();
      message.error('导出失败');
    }
  };

  const columns = useMemo(() => [
    {
      title: '创作者ID',
      dataIndex: 'creator_id',
      key: 'creator_id',
      width: 120,
    },
    {
      title: '头像',
      dataIndex: 'avatar',
      key: 'avatar',
      width: 60,
      render: (avatar) => avatar ? <Avatar src={avatar} size={32} /> : <Avatar size={32} icon={<UserOutlined />} />,
    },
    {
      title: '昵称',
      dataIndex: 'nickname',
      key: 'nickname',
      width: 150,
      onCell: (record: Creator) => ({
        onClick: () => handleViewDetail(record),
        style: { cursor: 'pointer' },
      }),
    },
    {
      title: '粉丝数',
      dataIndex: 'followers',
      key: 'followers',
      align: 'right' as const,
      width: 100,
      render: formatNumber,
    },
    {
      title: '总销量',
      dataIndex: 'total_sales',
      key: 'total_sales',
      align: 'right' as const,
      width: 100,
      render: formatNumber,
    },
    {
      title: '总收入',
      dataIndex: 'total_revenue',
      key: 'total_revenue',
      align: 'right' as const,
      width: 120,
      render: (v) => '¥' + formatNumber(v),
    },
    {
      title: '带货商品数',
      dataIndex: 'product_count',
      key: 'product_count',
      align: 'right' as const,
      width: 100,
      render: formatNumber,
    },
    {
      title: '平均转化率',
      dataIndex: 'avg_conversion_rate',
      key: 'avg_conversion_rate',
      align: 'right' as const,
      width: 120,
      render: (v) => v ? ((v as number) * 100).toFixed(2) + '%' : '-',
    },
    {
      title: '更新时间',
      dataIndex: 'fetched_at',
      key: 'fetched_at',
      width: 160,
      render: formatDateTime,
    },
  ], [handleViewDetail]);

  const filteredData = useMemo(() => {
    const creators = (data?.data as Creator[]) || [];
