interface StatCardProps {
  label: string;
  value: string | number;
  trend?: number;
  trendLabel: string;
  prefix?: React.ReactNode;
  suffix?: React.ReactNode;
  loading?: boolean;
  error?: Error | null;
  subValue?: string;
  subLabel?: string;
}

const StatCard = ({ label, value, trend, trendLabel, prefix, suffix, loading, error, subValue, subLabel }: StatCardProps) => {
  const safeTrend = trend ?? 0;
  const trendCls = getTrendClass(safeTrend, 0);
  return (
    <Card className={`${styles.statCard} ${trendCls}`}>
      <div className={styles.label}>{label}</div>
      <Statistic
        value={value}
        prefix={prefix}
        suffix={suffix}
        loading={loading}
        valueStyle={{ fontSize: 28, fontWeight: 600 }}
      />
      {subValue && (
        <div className={styles.subValue}>
          <span className={styles.subLabel}>{subLabel}:</span>
          <span>{subValue}</span>
        </div>
      )}
      {trend !== undefined && (
        <div className={`${styles.trend} ${trendCls}`}>
          {safeTrend > 0 ? <RiseOutlined /> : safeTrend < 0 ? <FallOutlined /> : <span>→</span>}
          {Math.abs(safeTrend).toFixed(1)}% {trendLabel}
        </div>
      )}
      {error && <Alert message="加载失败" description={error.message} type="error" />}
    </Card>
  );
};

interface TrendChartData {
  date: string;
  sales?: number;
  revenue?: number;
  orders?: number;
  conversion?: number;
}

interface TrendChartProps {
  data: TrendChartData[];
  metric: 'sales' | 'revenue' | 'orders' | 'conversion';
  title: string;
  color: string;
  formatter?: (value: number) => string;
}

const TrendChart = ({ data, metric, title, color, formatter }: TrendChartProps) => {
  if (!data || data.length === 0) return null;

  const chartData = data.map(d => ({
    date: d.date,
    value: d[metric] ?? 0,
  }));

  const MetricChart = metric === 'conversion' ? LineChart : BarChart;

  return (
    <Card className={styles.chartContainer}>
      <div className={styles.chartTitle}>
        <span>{title}</span>
      </div>
      <ResponsiveContainer width="100%" height={280}>
        <MetricChart data={chartData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
          <XAxis dataKey="date" stroke="#999" fontSize={12} tick={{ fill: '#999' }} />
          <YAxis stroke="#999" fontSize={12} tickFormatter={(value: number) => formatter ? formatter(value) : formatNumber(value)} tick={{ fill: '#999' }} />
          <Tooltip 
            formatter={(value: number) => [formatter ? formatter(value) : formatNumber(value), title]} 
            labelFormatter={(date: string) => `日期: ${date}`}
          />
          <Legend />
          {metric === 'conversion' ? (
            <Line
              type="monotone"
              dataKey="value"
              stroke={color}
              strokeWidth={2}
              dot={{ fill: color, strokeWidth: 2, r: 4 }}
              activeDot={{ r: 6 }}
            />
          ) : (
            <Bar
              dataKey="value"
              fill={color}
              radius={[4, 4, 0, 0]}
              barSize={40}
            />
          )}
        </MetricChart>
      </ResponsiveContainer>
    </Card>
  );
};

interface ComparisonCardProps {
  label: string;
  today: number;
  yesterday: number;
  formatter: (v: number) => string;
  prefix?: React.ReactNode;
  icon?: React.ReactNode;
}

const ComparisonCard = ({ label, today, yesterday, formatter, prefix, icon }: ComparisonCardProps) => {
  const growth = calculateGrowth(today, yesterday);
  const trendCls = getTrendClass(today, yesterday);
  return (
    <Card className={`${styles.comparisonCard} ${trendCls}`}>
      <div className={styles.compLabel}>
        {icon ? <span className={styles.compIcon}>{icon}</span> : null}
        {label}
      </div>
      <div className={styles.compValues}>
        <div className={styles.compToday}>
          <Statistic value={formatter(today)} prefix={prefix} valueStyle={{ fontSize: 24, fontWeight: 600 }} />
          <span className={styles.todayLabel}>今日</span>
        </div>
        <div className={styles.compYesterday}>
          <Statistic value={formatter(yesterday)} valueStyle={{ fontSize: 14, color: '#8c8c8c' }} />
          <span className={styles.yesterdayLabel}>昨日</span>
        </div>
      </div>
      <div className={`${styles.compTrend} ${trendCls}`}>
        {growth > 0 ? <RiseOutlined /> : growth < 0 ? <FallOutlined /> : <span>→</span>}
        {Math.abs(growth).toFixed(1)}%
      </div>
    </Card>
  );
};

