const { RangePicker } = DatePicker;
type DateRangeValue = [dayjs.Dayjs, dayjs.Dayjs] | [];

const ImageEdit = () => {
  const [searchText, setSearchText] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [dateRange, setDateRange] = useState<DateRangeValue>([]);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);

  const { data, loading, error, refetch } = useApi<PaginatedResponse<MediaItem>>(
    () => mediaApi.getImageEditList({ 
      page, 
      size: pageSize, 
      keyword: searchText,
      status: statusFilter,
      start_date: dateRange[0]?.format('YYYY-MM-DD'),
      end_date: dateRange[1]?.format('YYYY-MM-DD'),
    }),
    [page, pageSize, searchText, statusFilter, dateRange]
  );

  const handleSearch = (e) => {
    setSearchText(e.target.value);
    setPage(1);
  };

  const handleDateChange = (dates) => {
    setDateRange(dates);
    setPage(1);
  };

  const handleStatusChange = (value) => {
    setStatusFilter(value);
    setPage(1);
  };

  const handleTableChange = (pagination) => {
    if (pagination) {
      setPage(pagination.current);
      setPageSize(pagination.pageSize);
    }
  };

  const handleStartEdit = async (record: MediaItem) => {
    try {
      message.loading('启动编辑...', 0);
      message.destroy();
      message.success('编辑任务已启动');
      refetch();
    } catch (err) {
      message.destroy();
      message.error('启动失败');
    }
  };

  const columns = useMemo(() => [
    {
      title: '图片ID',
      dataIndex: 'image_id',
      key: 'image_id',
      width: 120,
    },
    {
      title: '图片名称',
      dataIndex: 'title',
      key: 'title',
      width: 200,
      ellipsis: true,
    },
    {
      title: '原始图片',
      dataIndex: 'source_image',
      key: 'source_image',
      width: 100,
      render: (v) => v ? <img src={v} alt="原图" style={{ width: 60, height: 60, objectFit: 'cover', borderRadius: 4 }} /> : '-',
    },
    {
      title: '编辑状态',
      dataIndex: 'edit_status',
      key: 'edit_status',
      width: 100,
      align: 'center' as const,
      render: (status) => (
        <Tag color={status === 'editing' ? 'processing' : status === 'completed' ? 'success' : 'default'}>
          {status === 'editing' ? '编辑中' : status === 'completed' ? '已完成' : status}
        </Tag>
      ),
    },
    {
      title: '输出格式',
      dataIndex: 'output_format',
      key: 'output_format',
      width: 100,
    },
    {
      title: '分辨率',
      dataIndex: 'resolution',
      key: 'resolution',
      width: 120,
    },
    {
      title: '文件大小',
      dataIndex: 'file_size',
      key: 'file_size',
      width: 120,
      render: (v) => v ? (v / 1024 / 1024).toFixed(2) + ' MB' : '-',
    },
    {
      title: '创建时间',
      dataIndex: 'create_time',
      key: 'create_time',
      width: 180,
      render: formatDateTime,
    },
    {
      title: '操作',
      key: 'action',
      width: 180,
      render: (_, record: MediaItem) => (
        <Space>
          <Button type="link" icon={<EyeOutlined />} size="small">预览</Button>
          <Button type="link" icon={<EditOutlined />} size="small">编辑</Button>
          <Button type="link" icon={<DeleteOutlined />} size="small" danger>删除</Button>
        </Space>
      ),
    },
  ], []);

  if (loading && !data) {
    return <Spin size="large" tip="加载图片编辑数据..." />;
  }

  if (error) {
    return (
      <Card>
        <div style={{ textAlign: 'center', padding: 40 }}>
          <p style={{ color: '#ff4d4f' }}>加载失败: {error.message}</p>
          <Button type="primary" onClick={refetch} icon={<ReloadOutlined />}>
            重试
          </Button>
        </div>
      </Card>
    );
  }

  const imageList = data?.data || [];
  const total = data?.total || 0;

  return (
    <div className="page-container">
      <div className="page-header">
        <h1 className="page-title">图片编辑</h1>
        <Space wrap>
          <Input
            placeholder="搜索图片名称..."
            value={searchText}
            onChange={(e) => { setSearchText(e.target.value); setPage(1); }}
            prefix={<SearchOutlined />}
            style={{ width: 250 }}
            allowClear
          />
          <Select
            placeholder="编辑状态"
            value={statusFilter}
            onChange={(value) => { setStatusFilter(value); setPage(1); }}
            allowClear
            style={{ width: 140 }}
            options={[
              { value: 'editing', label: '编辑中' },
              { value: 'completed', label: '已完成' },
              { value: 'failed', label: '失败' },
            ]}
          />
          <Button type="primary" icon={<PictureOutlined />} onClick={handleNewEdit}>新建编辑任务</Button>
          <Button icon={<DownloadOutlined />} onClick={handleExport}>导出 CSV</Button>
          <Button icon={<ReloadOutlined />} onClick={refetch} loading={loading}>刷新</Button>
        </Space>
      </div>

      <Card className="table-container">
        <Table
          columns={columns}
          dataSource={imageList}
          pagination={{
            current: page,
            pageSize,
            total,
            showSizeChanger: true,
            showQuickJumper: true,
            showTotal: (total) => `共 ${total} 条`,
          }}
          rowKey="image_id"
          loading={loading}
          scroll={{ x: 1300 }}
        />
      </Card>
    </div>
  );
};

const handleNewEdit = () => {
  message.info('新建编辑任务功能开发中...');
};

const handleExport = async () => {
  try {
    message.loading('导出中...', 0);
    const result = await mediaApi.getImageEditList({ page: 1, size: 10000 });
