            onChange={handleStatusChange}
            allowClear
            style={{ width: 140 }}
            options={[
              { value: 'published', label: '已发布' },
              { value: 'draft', label: '草稿' },
              { value: 'pending', label: '待审核' },
              { value: 'rejected', label: '已驳回' },
            ]}
          />
          <Button icon={<DownloadOutlined />} onClick={handleExport}>导出 CSV</Button>
          <Button icon={<ReloadOutlined />} onClick={refetch} loading={loading}>刷新</Button>
        </Space>
      </div>

      <Card className="table-container">
        <Table
          columns={columns}
          dataSource={videos}
          pagination={{
            current: page,
            pageSize,
            total,
            showSizeChanger: true,
            showQuickJumper: true,
            showTotal: (total) => `共 ${total} 条`,
          }}
          onChange={handleTableChange}
          rowKey="video_id"
          loading={loading}
          scroll={{ x: 1300 }}
        />
      </Card>
    </div>
  );
};

const handleExport = async () => {
  try {
    message.loading('导出中...', 0);
    const result = await videoApi.getList({ page: 1, size: 10000 });
    message.destroy();

    const csvContent = [
      ['视频ID', '标题', '创作者', '播放量', '点赞数', '评论数', '分享数', '状态', '发布时间'],
      ...(result?.data || []).map(v => [
        v.video_id,
        v.title,
        v.creator_name,
        v.play_count,
        v.like_count,
        v.comment_count,
        v.share_count,
        v.status,
        v.create_time,
      ]),
    ].map(row => row.map(cell => `"${cell}"`).join(',')).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `videos_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
    message.success('导出成功');
  } catch (err) {
    message.destroy();
    message.error('导出失败');
  }
};

export default Videos;
